use crate::benchmark::corpus::{BenchmarkCase, BenchmarkCorpus, BenchmarkError};
use crate::benchmark::metrics::{BenchmarkMetrics, CaseEvaluation, ClassificationKind};
use crate::types::EvidenceCertainty;
use chrono::Utc;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::time::Instant;

/// Output prediction generated by a classifier for a benchmark case.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct BenchmarkPrediction {
    pub vulnerable: bool,
    pub rule_ids: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub certainty: Option<EvidenceCertainty>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub details: Option<String>,
}

impl BenchmarkPrediction {
    /// Helper to construct a clean non-vulnerable prediction.
    pub fn safe() -> Self {
        Self {
            vulnerable: false,
            rule_ids: Vec::new(),
            certainty: None,
            details: None,
        }
    }

    /// Helper to construct a vulnerable prediction with matched rules and optional certainty.
    pub fn vulnerable(rule_ids: Vec<String>, certainty: Option<EvidenceCertainty>) -> Self {
        Self {
            vulnerable: true,
            rule_ids,
            certainty,
            details: None,
        }
    }
}

/// Interface for any detector, classifier, or heuristic evaluated by the benchmark runner.
pub trait BenchmarkClassifier: Send + Sync {
    /// Human-readable identifier of the classifier under test.
    fn name(&self) -> &str;

    /// Evaluates a single benchmark case given its metadata and fixture source content.
    fn predict(&self, case: &BenchmarkCase, fixture_content: &str) -> BenchmarkPrediction;
}

/// Ergonomic wrapper allowing any closure to act as a `BenchmarkClassifier`.
pub struct FnClassifier<F> {
    name: String,
    func: F,
}

impl<F> FnClassifier<F>
where
    F: Fn(&BenchmarkCase, &str) -> BenchmarkPrediction + Send + Sync,
{
    pub fn new(name: impl Into<String>, func: F) -> Self {
        Self {
            name: name.into(),
            func,
        }
    }
}

impl<F> BenchmarkClassifier for FnClassifier<F>
where
    F: Fn(&BenchmarkCase, &str) -> BenchmarkPrediction + Send + Sync,
{
    fn name(&self) -> &str {
        &self.name
    }

    fn predict(&self, case: &BenchmarkCase, fixture_content: &str) -> BenchmarkPrediction {
        (self.func)(case, fixture_content)
    }
}

/// Metadata proving provenance, inputs, and determinism of a benchmark report.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ReproducibilityManifest {
    pub corpus_fingerprint: String,
    pub case_count: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ruleset_digest: Option<String>,
    pub classifier_name: String,
    pub report_fingerprint: String,
}

/// Deterministic report summarizing the results of running a classifier against a corpus.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct BenchmarkReport {
    pub report_version: String,
    pub timestamp: String,
    pub classifier_name: String,
    pub corpus_fingerprint: String,
    pub total_cases: usize,
    pub metrics: BenchmarkMetrics,
    pub case_evaluations: Vec<CaseEvaluation>,
    pub duration_ms: u64,
    pub reproducibility: ReproducibilityManifest,
}

impl BenchmarkReport {
    /// Computes a deterministic SHA-256 fingerprint over the report's canonical evaluation outcomes.
    pub fn compute_report_fingerprint(
        corpus_fingerprint: &str,
        classifier_name: &str,
        metrics: &BenchmarkMetrics,
        evaluations: &[CaseEvaluation],
    ) -> String {
        let mut hasher = Sha256::new();
        hasher.update(b"BUG_KILLER_BENCHMARK_REPORT_V1\n");
        hasher.update(corpus_fingerprint.as_bytes());
        hasher.update(b"\n");
        hasher.update(classifier_name.as_bytes());
        hasher.update(b"\n");
        hasher.update(format!("TOTAL:{}\n", evaluations.len()).as_bytes());
        hasher.update(
            format!(
                "OVERALL:TP={},FP={},FN={},TN={}\n",
                metrics.overall.tp,
                metrics.overall.fp,
                metrics.overall.fn_count,
                metrics.overall.tn
            )
            .as_bytes(),
        );

        // Include CWE breakdown in deterministic key order
        for (cwe, cm) in &metrics.by_cwe {
            hasher.update(
                format!(
                    "CWE:{}:TP={},FP={},FN={},TN={}\n",
                    cwe, cm.tp, cm.fp, cm.fn_count, cm.tn
                )
                .as_bytes(),
            );
        }

        // Include Language breakdown in deterministic key order
        for (lang, cm) in &metrics.by_language {
            hasher.update(
                format!(
                    "LANG:{}:TP={},FP={},FN={},TN={}\n",
                    lang, cm.tp, cm.fp, cm.fn_count, cm.tn
                )
                .as_bytes(),
            );
        }

        // Include individual evaluations sorted by case_id
        let mut sorted_evals = evaluations.to_vec();
        sorted_evals.sort_by(|a, b| a.case_id.cmp(&b.case_id));
        for eval in sorted_evals {
            hasher.update(eval.case_id.as_bytes());
            hasher.update(b"|");
            hasher.update(eval.classification.as_str().as_bytes());
            hasher.update(b"|");
            hasher.update(if eval.expected_vulnerable {
                b"E1|"
            } else {
                b"E0|"
            });
            hasher.update(if eval.predicted_vulnerable {
                b"P1|"
            } else {
                b"P0|"
            });
            let mut sorted_rules = eval.matched_rules.clone();
            sorted_rules.sort();
            for r in sorted_rules {
                hasher.update(r.as_bytes());
                hasher.update(b",");
            }
            hasher.update(b"\n");
        }

        crate::to_hex(hasher.finalize())
    }
}

/// Harness for executing security benchmark evaluations.
pub struct BenchmarkRunner {
    pub corpus: BenchmarkCorpus,
}

impl BenchmarkRunner {
    /// Creates a runner bound to a verified corpus.
    pub fn new(corpus: BenchmarkCorpus) -> Self {
        Self { corpus }
    }

    /// Runs a classifier against all cases in the corpus using real wall-clock timing and current UTC timestamp.
    pub fn run<C: BenchmarkClassifier>(
        &self,
        classifier: &C,
    ) -> Result<BenchmarkReport, BenchmarkError> {
        let start = Instant::now();
        let timestamp = Utc::now().to_rfc3339();

        let evaluations = self.evaluate_cases(classifier)?;
        let duration_ms = start.elapsed().as_millis() as u64;

        self.assemble_report(classifier.name(), evaluations, timestamp, duration_ms)
    }

    /// Runs a classifier with an explicit fixed timestamp and duration for deterministic testing.
    pub fn run_deterministic<C: BenchmarkClassifier>(
        &self,
        classifier: &C,
        timestamp: &str,
        duration_ms: u64,
    ) -> Result<BenchmarkReport, BenchmarkError> {
        let evaluations = self.evaluate_cases(classifier)?;
        self.assemble_report(
            classifier.name(),
            evaluations,
            timestamp.to_string(),
            duration_ms,
        )
    }

    fn evaluate_cases<C: BenchmarkClassifier>(
        &self,
        classifier: &C,
    ) -> Result<Vec<CaseEvaluation>, BenchmarkError> {
        let mut evaluations = Vec::with_capacity(self.corpus.cases.len());

        for case in &self.corpus.cases {
            let fixture_content = self.corpus.read_fixture(case)?;
            let prediction = classifier.predict(case, &fixture_content);

            let classification =
                ClassificationKind::classify(case.expected_vulnerable, prediction.vulnerable);

            evaluations.push(CaseEvaluation {
                case_id: case.case_id.clone(),
                weakness: case.weakness.clone(),
                language: case.language.clone(),
                expected_vulnerable: case.expected_vulnerable,
                predicted_vulnerable: prediction.vulnerable,
                classification,
                passed: classification.is_pass(),
                matched_rules: prediction.rule_ids,
                predicted_certainty: prediction.certainty,
                details: prediction.details,
            });
        }

        Ok(evaluations)
    }

    fn assemble_report(
        &self,
        classifier_name: &str,
        evaluations: Vec<CaseEvaluation>,
        timestamp: String,
        duration_ms: u64,
    ) -> Result<BenchmarkReport, BenchmarkError> {
        let metrics = BenchmarkMetrics::from_evaluations(&evaluations);
        let total_cases = evaluations.len();

        let report_fingerprint = BenchmarkReport::compute_report_fingerprint(
            &self.corpus.dataset_fingerprint,
            classifier_name,
            &metrics,
            &evaluations,
        );

        let reproducibility = ReproducibilityManifest {
            corpus_fingerprint: self.corpus.dataset_fingerprint.clone(),
            case_count: total_cases,
            ruleset_digest: None,
            classifier_name: classifier_name.to_string(),
            report_fingerprint,
        };

        Ok(BenchmarkReport {
            report_version: "1.0.0".to_string(),
            timestamp,
            classifier_name: classifier_name.to_string(),
            corpus_fingerprint: self.corpus.dataset_fingerprint.clone(),
            total_cases,
            metrics,
            case_evaluations: evaluations,
            duration_ms,
            reproducibility,
        })
    }
}

/// Kind of external adversarial red-team framework used to stress-test defensive postures.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum AdversarialFrameworkKind {
    Shannon,
    Strix,
    DeepAudit,
    Drakben,
    Xalgorix,
    Custom,
}

impl AdversarialFrameworkKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            AdversarialFrameworkKind::Shannon => "Shannon",
            AdversarialFrameworkKind::Strix => "Strix",
            AdversarialFrameworkKind::DeepAudit => "DeepAudit",
            AdversarialFrameworkKind::Drakben => "Drakben",
            AdversarialFrameworkKind::Xalgorix => "Xalgorix",
            AdversarialFrameworkKind::Custom => "Custom",
        }
    }
}

/// An evaluation case representing an adversarial exploit candidate or attack vector.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AdversarialAttackVector {
    pub vector_id: String,
    pub framework: AdversarialFrameworkKind,
    pub target_subsystem: String,
    pub payload_signature: String,
    pub simulated_threat: String,
}

/// Result of evaluating an adversarial attack vector against defensive virtual patching / detection.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AdversarialEvaluationResult {
    pub vector_id: String,
    pub blocked: bool,
    pub mitigated_by: Option<String>,
    pub defense_latency_ms: u64,
}

/// A structured evaluation report quantifying defensive posture against red-team attack vectors.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AdversarialBenchmarkReport {
    pub report_id: String,
    pub framework: AdversarialFrameworkKind,
    pub timestamp: String,
    pub total_vectors: usize,
    pub blocked_count: usize,
    pub bypassed_count: usize,
    pub mitigation_rate: f64,
    pub results: Vec<AdversarialEvaluationResult>,
}

/// Defensive test runner for adversarial benchmark suites.
pub struct AdversarialBenchmarkRunner {
    pub framework: AdversarialFrameworkKind,
    pub vectors: Vec<AdversarialAttackVector>,
}

impl AdversarialBenchmarkRunner {
    pub fn new(framework: AdversarialFrameworkKind) -> Self {
        Self {
            framework,
            vectors: Vec::new(),
        }
    }

    pub fn add_vector(&mut self, vector: AdversarialAttackVector) {
        self.vectors.push(vector);
    }

    /// Evaluates all attack vectors against a defensive gate or virtual patch evaluator.
    pub fn evaluate<F>(&self, defense_evaluator: F) -> AdversarialBenchmarkReport
    where
        F: Fn(&AdversarialAttackVector) -> (bool, Option<String>),
    {
        let mut results = Vec::new();
        let mut blocked_count = 0;

        for vec in &self.vectors {
            let start = Instant::now();
            let (blocked, mitigated_by) = defense_evaluator(vec);
            let elapsed = start.elapsed().as_millis() as u64;

            if blocked {
                blocked_count += 1;
            }

            results.push(AdversarialEvaluationResult {
                vector_id: vec.vector_id.clone(),
                blocked,
                mitigated_by,
                defense_latency_ms: elapsed,
            });
        }

        let total = self.vectors.len();
        let bypassed = total.saturating_sub(blocked_count);
        let rate = if total > 0 {
            (blocked_count as f64) / (total as f64)
        } else {
            1.0
        };

        let mut hasher = Sha256::new();
        hasher.update(self.framework.as_str().as_bytes());
        hasher.update(total.to_string().as_bytes());
        let report_id = format!("adv-{}", &crate::to_hex(hasher.finalize())[..16]);

        AdversarialBenchmarkReport {
            report_id,
            framework: self.framework,
            timestamp: Utc::now().to_rfc3339(),
            total_vectors: total,
            blocked_count,
            bypassed_count: bypassed,
            mitigation_rate: rate,
            results,
        }
    }
}
